    class watchdog_regs extends uvm_reg_block;
        rand watchdog_regs__IP_ID IP_ID;
        rand watchdog_regs__VERSION VERSION;
        rand watchdog_regs__CAPABILITY0 CAPABILITY0;
        rand watchdog_regs__CAPABILITY1 CAPABILITY1;
        rand watchdog_regs__CMD_STATUS CMD_STATUS;
