        rand watchdog_regs__DONE_SEQ DONE_SEQ;
        rand watchdog_regs__DONE_INFO DONE_INFO;
        rand watchdog_regs__IRQ_SUMMARY IRQ_SUMMARY;
        rand watchdog_regs__FAULT_SUMMARY FAULT_SUMMARY;
        rand watchdog_regs__RESET_SUMMARY RESET_SUMMARY;
        rand watchdog_regs__channel_regs ch[16];

        function new(string name = "watchdog_regs");
            super.new(name);
        endfunction : new

